it('strips article body before the extract step sees it', async () => {
  const articles: FeedArticle[] = [
    makeArticle(1, '2026-04-01T08:00:00.000Z', 200),
    makeArticle(2, '2026-04-01T07:00:00.000Z', 200),
  ];

  await runPipeline({
    from: '2026-04-01',
    configPath: writeConfig(),
    stopAfter: 'extract',
    feedSource: {
      loadArticles: async () => articles,
      close: () => undefined,
    },
    stepRunners: {
      extract: async (_config, _services, prev) => {
        extractInput = prev as { articles: FeedArticle[] | string };
        return [];
      },
    },
  });

  expect(extractInput).not.toBeNull();
  const articlesOut = extractInput!.articles;
  expect(Array.isArray(articlesOut)).toBe(true);
  for (const a of articlesOut as FeedArticle[]) {
    // Chunks carry the text; body must NOT cross the boundary.
    expect(a.body).toBe('');
    expect(Array.isArray((a as unknown as { chunks: unknown[] }).chunks)).toBe(true);
  }
});

